import { extractHTMLMetadata } from "./metadata-extraction.js";
import { buildStructuredManagedHeadDescriptors, generateLinkTags, generateMetaTags, generateScriptTags, generateStyleTags, } from "./tag-generators.js";
import { serializeManagedHeadPayload } from "./managed-head-protocol.js";
